package com.lyrashop.user.controller;import java.util.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import com.lyrashop.user.service.LoyaltyService;
@RestController @RequestMapping("/api/v1/me/loyalty") public class LoyaltyController{private final LoyaltyService s;public LoyaltyController(LoyaltyService s){this.s=s;}private UUID id(Authentication a){return UUID.fromString(a.getName());}@GetMapping public Map<String,Object> get(Authentication a){return s.get(id(a));}@PostMapping("/check-in") public Map<String,Object> check(Authentication a){return s.checkIn(id(a));}@GetMapping("/transactions") public List<Map<String,Object>> history(Authentication a){return s.history(id(a));}}
